5. 실무 활용 팁
💡 Tip 1: BaseEntity 추상 클래스 활용
// 공통 Audit 필드
abstract class BaseEntity(
@CreatedDate
var createdAt: LocalDateTime? = null,
@LastModifiedDate
var updatedAt: LocalDateTime? = null,
@CreatedBy
var createdBy: String? = null,
@LastModifiedBy
var updatedBy: String? = null
)
// 사용
@Document(collection = "users")
data class User(...) : BaseEntity()
@Document(collection = "products")
data class Product(...) : BaseEntity()
@Document(collection = "orders")
data class Order(...) : BaseEntity()
장점:
모든 Entity에 일관되게 Audit 필드 적용
한 곳만 수정하면 모든 Entity에 반영
코드 중복 제거
💡 Tip 2: Spring Security와 연동
@Configuration
@EnableMongoAuditing
class MongoAuditConfig {
@Bean
fun auditorProvider(): AuditorAware<String> {
return AuditorAware {
val auth = SecurityContextHolder.getContext().authentication
when {
// 1. JWT 토큰에서 사용자 정보 추출
auth?.principal is JwtUser -> {
val user = auth.principal as JwtUser
Optional.of(user.userId)
}
// 2. 일반 인증 정보
auth != null && auth.isAuthenticated -> {
Optional.of(auth.name)
}
// 3. 인증 정보 없음 (배치 작업 등)
else -> Optional.of("system")
}
}
}
}
